    for(const auto& [name,encoded]:rows) {
        std::istringstream input(encoded);
        std::string token;
        auto& ideology=out.ideologies[name];
        while(input>>token) {
            const auto split=token.rfind(':');
            if(split==std::string::npos)
                throw std::logic_error("POLITICS_REFERENCE_IDEOLOGY_SYNTAX");
            const auto law=token.substr(0,split);
            const auto l=out.laws.find(law);
            if(l==out.laws.end())
                throw std::logic_error("POLITICS_UNKNOWN_REFERENCE_LAW");
            const int value=std::stoi(token.substr(split+1));
            if(value<-2||value>2)
                throw std::logic_error("POLITICS_INVALID_REFERENCE_STANCE");
            ideology[l->second.group+"/"+law]=
                static_cast<std::int8_t>(value);
        }
    }
